-- Seed quiz propositions + ideology stances for politica/ideologias (BR).
-- Generated by scripts/generate_quiz_seed.py — do not hand-edit lightly.

WITH host AS (
  SELECT id
  FROM public.groups
  WHERE slug = 'politica/ideologias'
    AND country_code = 'br'
  LIMIT 1
),
leaf_issues AS (
  SELECT i.id, i.slug
  FROM public.issues i
  JOIN host h ON i.group_id = h.id
  WHERE NOT EXISTS (
    SELECT 1 FROM public.issues c WHERE c.parent_issue_id = i.id
  )
),
prop_src AS (
  SELECT * FROM (VALUES
  ('tamanho-do-estado', 10, 'Os estados modernos têm atribuições demais.'),
  ('drogas', 20, 'O uso adulto de drogas deve ser descriminalizado (ou legalizado) e tratado sobretudo como questão de liberdade/saúde, não de repressão penal ampla.'),
  ('habitacao', 30, 'O Estado deve garantir o direito à moradia através de subsídio, regulação de aluguel e/ou provisão estatal.'),
  ('saneamento', 40, 'Saneamento básico universal deve ser prioridade pública, mesmo exigindo investimento elevado e regulação forte.'),
  ('transporte', 50, 'Transporte público de qualidade deve ser prioridade do Estado, com forte investimento e, se necessário, subsidiado.'),
  ('cultura', 60, 'O Estado deve financiar e promover cultura (editais, incentivos, mídia pública) como política permanente.'),
  ('fronteiras', 70, 'O controle rígido de fronteiras é necessário à soberania e à ordem pública.'),
  ('imigracao', 80, 'A imigração deve ser amplamente acolhida, com regras generosas de entrada e integração.'),
  ('geopolitica', 90, 'O Brasil deve priorizar alinhamentos soberanos e multipolares, evitando subordinação a blocos liderados por potências ocidentais.'),
  ('legislacao', 100, 'Em geral, é melhor ter menos leis e mais liberdade contratual do que um ordenamento denso que tenta regular a vida social em detalhe.'),
  ('eleicoes', 110, 'Eleições competitivas com voto universal são a forma legítima central de decidir o poder político.'),
  ('armamento', 120, 'Cidadãos cumpridores da lei devem ter amplo direito de possuir armas de fogo.'),
  ('energia', 130, 'A transição energética (renováveis, descarbonização) deve ser acelerada mesmo com custos econômicos relevantes no curto prazo.'),
  ('defesa', 140, 'Manter Forças Armadas nacionais fortes e bem financiadas é prioridade inegociável do Estado.'),
  ('welfare', 150, 'Programas amplos de assistência social (transferência de renda, benefícios) são justos e necessários.'),
  ('previdencia', 160, 'A previdência deve permanecer predominantemente pública e solidária (repartição), não privatizada.'),
  ('racismo', 170, 'O racismo é um problema estrutural que exige políticas públicas específicas e contínuas de combate.'),
  ('povos-originarios', 180, 'Demarcação e proteção forte de terras indígenas devem prevalecer mesmo diante de interesses econômicos (agro, mineração, infraestrutura).'),
  ('privacidade', 190, 'A privacidade individual deve ter proteção forte contra vigilância estatal e corporativa, mesmo em nome de segurança ou eficiência.'),
  ('agronegocio', 200, 'O agronegócio de exportação deve ser prioridade estratégica nacional, com apoio político e regulatório.'),
  ('trabalhismo', 210, 'A legislação trabalhista deve proteger fortemente o trabalhador (estabilidade, encargos, limites à demissão), mesmo reduzindo flexibilidade do empregador.'),
  ('aborto', 220, 'O aborto deve ser legal e acessível por decisão da gestante, ao menos no início da gestação.'),
  ('eutanasia', 230, 'A eutanásia/morte assistida voluntária deve ser legal em condições reguladas.'),
  ('sistema-publico-de-saude', 240, 'Um sistema público universal de saúde (tipo SUS) deve ser mantido e fortalecido como pilar central.'),
  ('vacinas', 250, 'Vacinas comprovadamente eficazes devem poder ser exigidas em contextos de saúde pública (escolas, epidemias), mesmo limitando escolhas individuais.'),
  ('homeschooling', 260, 'Famílias devem ter amplo direito de educar em casa (homeschooling), com pouca interferência estatal.'),
  ('universidades', 270, 'Ensino superior público gratuito (ou fortemente subsidiado) deve ser ampliado e priorizado.'),
  ('crime-organizado', 280, 'O combate ao crime organizado exige endurecimento penal e repressão estatal intensa.'),
  ('linguagem-neutra', 290, 'Instituições públicas devem adotar e incentivar linguagem neutra/inclusiva de gênero.'),
  ('casamento-homoafetivo', 300, 'Casais do mesmo sexo devem ter pleno direito ao casamento civil igualitário.'),
  ('adocao-lgbtq', 310, 'Casais LGBTQ+ devem ter o mesmo direito de adotar que casais hétero.'),
  ('mulheres-trans-esportes', 320, 'Mulheres trans devem poder competir em categorias esportivas femininas conforme identidade de gênero.'),
  ('banheiro-lgbtq', 330, 'Pessoas devem usar banheiros conforme identidade de gênero, inclusive em espaços públicos/escolares.'),
  ('sistema-prisional', 340, 'O sistema prisional deve priorizar ressocialização e redução do encarceramento, não punição dura.'),
  ('pena-de-morte', 350, 'A pena de morte deve existir para crimes hediondos graves.'),
  ('mudancas-climaticas', 360, 'Mudanças climáticas antropogênicas exigem ação política urgente e vinculante (metas, regulação, custos econômicos).'),
  ('cotas-raciais', 370, 'Cotas raciais em universidades e concursos são justas e necessárias.'),
  ('protecionismo', 380, 'O Estado deve proteger a indústria nacional com tarifas e barreiras comerciais quando necessário.'),
  ('regulacoes', 390, 'Em geral, há regulação econômica demais; o mercado precisa de bem menos regras.'),
  ('impostos', 400, 'A carga tributária deve ser bem menor do que a atual; impostos altos são, em regra, ilegítimos ou nocivos.'),
  ('soberania', 410, 'A soberania nacional deve prevalecer sobre normas e pressões internacionais quando houver conflito.'),
  ('laicidade-do-estado', 420, 'O Estado deve ser estritamente laico, sem privilégios simbólicos ou materiais a religiões.'),
  ('desinformacao', 430, 'O Estado/plataformas devem poder restringir fortemente conteúdos considerados desinformação.'),
  ('crimes-contra-a-honra', 440, 'Calúnia, injúria e difamação devem continuar tipificadas e puníveis (limites penais à expressão).'),
  ('reforma-agraria', 450, 'Reforma agrária com desapropriação de terras improdutivas é justa e necessária.'),
  ('patentes', 460, 'Patentes fortes são legítimas e necessárias para inovação.'),
  ('pirataria', 470, 'Pirataria de conteúdo/software deve ser combatida com rigor legal.')
  ) AS v(issue_slug, sort_order, statement)
),
inserted AS (
  INSERT INTO public.quiz_propositions (issue_id, host_group_id, statement, sort_order, is_active)
  SELECT li.id, h.id, ps.statement, ps.sort_order, true
  FROM prop_src ps
  JOIN leaf_issues li ON li.slug = ps.issue_slug
  CROSS JOIN host h
  ON CONFLICT (issue_id) DO UPDATE
    SET statement = EXCLUDED.statement,
        sort_order = EXCLUDED.sort_order,
        host_group_id = EXCLUDED.host_group_id,
        is_active = true
  RETURNING id, issue_id
),
