INSERT INTO public.quiz_ideology_stances (proposition_id, group_id, stance)
SELECT p.id, g.id, ss.stance::smallint
FROM stance_src ss
JOIN leaf_issues li ON li.slug = ss.issue_slug
JOIN inserted p ON p.issue_id = li.id
JOIN public.groups g
  ON g.slug = ss.ideology_slug
 AND g.country_code = 'br'
ON CONFLICT (proposition_id, group_id) DO UPDATE
  SET stance = EXCLUDED.stance;
